// 动态代理：若代码直接访问 DATA[exam].parts / title / audio / timing 等，自动返回当前激活套卷的数据
['PET', 'KET'].forEach(exam => {
  if (!DATA[exam]) return;
  ['parts', 'title', 'audio', 'audioAlt', 'listenLimit', 'timing'].forEach(prop => {
    Object.defineProperty(DATA[exam], prop, {
      configurable: true,
      enumerable: true,
      get() {
        const pid = (typeof state !== 'undefined' && state.paperId) || 'test1';
        const p = (DATA[exam].papers && DATA[exam].papers[pid]) || (DATA[exam].papers && DATA[exam].papers.test1);
        return p ? p[prop] : undefined;
      }
    });
  });
});

